const listingRead=p.match(/^\/api\/listing\/([^/]+)$/);if(listingRead&&method==='GET'){await visiblePost(db,listingRead[1],u);const item=await one(db,postSelect+' WHERE p.id=?',listingRead[1]);return reply({post:(await withPostState(db,[item],u))[0]})}
if(p.startsWith('/api/people/')&&method==='GET'){const username=p.split('/').pop().toLowerCase();const profile=await one(db,'SELECT user_id FROM wm_profiles WHERE username=?',username);need(profile,'Profile not found',404);return reply({userId:profile.user_id})}
if(p==='/api/username'&&method==='GET'){const value=(url.searchParams.get('value')||'').toLowerCase();const valid=/^[a-z][a-z0-9_]{2,23}$/.test(value)&&!['admin','owner','support','api','control','wize','market','login','settings'].includes(value);return reply({available:valid&&!await one(db,'SELECT user_id FROM wm_profiles WHERE username=? AND user_id!=?',value,u?.id||'')})}
const connections=p.match(/^\/api\/profile\/([^/]+)\/connections$/);if(connections&&method==='GET'){const id=connections[1],kind=url.searchParams.get('kind')||'friends';need(['friends','following','followers'].includes(kind),'Invalid connection list');need(await one(db,'SELECT id FROM users WHERE id=?',id),'Profile not found',404);const people=kind==='friends'?await rows(db,profileSelect+" JOIN wm_friend_requests fr ON (fr.from_id=u.id OR fr.to_id=u.id) WHERE fr.status='accepted' AND (fr.from_id=? OR fr.to_id=?) AND u.id!=? ORDER BY u.name LIMIT 200",id,id,id):await rows(db,profileSelect+(kind==='following'?" JOIN wm_follows f ON f.target_id=u.id WHERE f.user_id=?":" JOIN wm_follows f ON f.user_id=u.id WHERE f.target_id=?")+' ORDER BY u.name LIMIT 200',id);return reply({people:await withFriends(db,people,u)})}
if(p.startsWith('/api/profile/')&&method==='GET'){const id=p.split('/').pop();const person=await one(db,profileSelect+" WHERE u.id=?",id);need(person,'Profile not found',404);const stats=await one(db,"SELECT (SELECT count(*) FROM wm_follows WHERE target_id=?) followers,(SELECT count(*) FROM wm_follows WHERE user_id=?) following,(SELECT count(*) FROM wm_deals WHERE status='completed' AND (buyer_id=? OR seller_id=?)) deals,EXISTS(SELECT 1 FROM wm_follows WHERE user_id=? AND target_id=?) followed,(SELECT count(*) FROM wm_posts WHERE user_id=? AND deleted_at IS NULL AND status='approved' AND group_id IS NULL) posts",id,id,id,id,u?.id||'',id,id);const friends=(await one(db,"SELECT count(*) n FROM wm_friend_requests WHERE status='accepted' AND (from_id=? OR to_id=?)",id,id)).n;return reply({profile:{...(await withFriends(db,[person],u))[0],...stats,friends},posts:await withPostState(db,await rows(db,feedSelect+" WHERE (p.user_id=? AND f.shared_by_id IS NULL OR f.shared_by_id=?) AND p.deleted_at IS NULL AND p.group_id IS NULL AND p.status='approved' ORDER BY f.feed_at DESC LIMIT 100",id,id),u)})}
const publicView=p.match(/^\/api\/posts\/([^/]+)\/view$/);if(publicView&&method==='POST')return await recordPostView(req,db,publicView[1],u);
need(u,'Sign in to continue',401);if(method!=='GET')await throttle(db,'write:'+u.id,120);
if(p==='/api/saved'&&method==='GET'){return reply({posts:await withPostState(db,await rows(db,postSelect+" JOIN wm_saved_posts sp ON sp.post_id=p.id WHERE sp.user_id=? AND p.deleted_at IS NULL AND p.status='approved' AND (p.group_id IS NULL OR EXISTS(SELECT 1 FROM wm_group_members gm WHERE gm.group_id=p.group_id AND gm.user_id=?)) ORDER BY sp.created_at DESC LIMIT 100",u.id,u.id),u)})}
